}

dir$t11.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir;
  switch (cF){
&VoucherExRateValid01;
    case 'ma_gd':
      dir$t11HiddenColumnByTran(p);
      break;
    case 'ma_ngv':
      dir$t11HiddenColumnByType(p);
      break;
    case 'ty_gia':
      p.calcExpressionAll(0, '!ty_gia');
      break;
    case 'ma_kh':
      p.request('Customer', '', ['ma_kh', 'ngay_ct', 'ma_nt']);
      break;
	case 'ma_dk_ngay':
      dir$t11HiddenColumnByDay(p);
      break;
    default:
      break;
  }
}
&VoucherExRateValid02;
dir$t11.prototype.gridDetailActionChange = function(gindex, action, r){
  var p = this._dir;
  if (action == 'AfterDeleteRow' || action == 'AfterAppendGrid') dir$t11DisabledMasterField(p, p.grid(gindex));
  return true;
}
